{
  "title": "A Tasty Stroll Through Mexico City",
  "summary": "A relaxed day of art, castle views, and plenty of good eating, all in the same leafy corner of the city.",
  "stops": [
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start with the castle for those early-bird legs and the best morning views over the park."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle wander through the Bosque to build an appetite, because today is really about the food."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Lalo! keeps our vegetarian crew happy and proves a proper meal can still feel like a market feast."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "Roma Norte gives us street-food energy, photo corners, and a slow local-life ramble before dinner."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Pujol is the big food moment, a long vegetarian-friendly send-off for the day."
    }
  ]
}
